('Guitar', 199.99, 2),
('Board Game', 29.99, 1);

=== 02_schema.sql.gz ===

CREATE DATABASE IF NOT EXISTS benchmark_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE benchmark_db;

CREATE TABLE IF NOT EXISTS categories (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE DEFINER=`devops`@`%` VIEW category_view AS
SELECT id, name FROM categories;

CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(20) NOT NULL,
    price DECIMAL(10, 2) NOT NULL,
    category_id INT,
    FOREIGN KEY (category_id) REFERENCES categories(id)
);

input.command:
set -e
# Create DB + user
mysql --socket=/var/run/mysqld/mysqld.sock -u root <<'SQL'
CREATE DATABASE IF NOT EXISTS benchmark_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS 'benchmark_user'@'localhost' IDENTIFIED WITH mysql_native_password BY 'benchmark_pass';
CREATE USER IF NOT EXISTS 'benchmark_user'@'%' IDENTIFIED WITH mysql_native_password BY 'benchmark_pass';
GRANT ALL PRIVILEGES ON benchmark_db.* TO 'benchmark_user'@'localhost';
GRANT ALL PRIVILEGES ON benchmark_db.* TO 'benchmark_user'@'%';
FLUSH PRIVILEGES;
SQL
echo "user/db created"

# Apply schema first (02), then seed (01) - strip DEFINER clause
zcat /testbed/migrations/02_schema.sql.gz | sed -E 's/DEFINER=`[^`]*`@`[^`]*`//g' | mysql --socket=/var/run/mysqld/mysqld.sock -u root
echo "schema applied"
zcat /testbed/migrations/01_seed.sql.gz | mysql --socket=/var/run/mysqld/mysqld.sock -u root benchmark_db
echo "seed applied"
